-- Additive MFA state. No existing account/session is enrolled or elevated.
CREATE TABLE "StaffMfaDevice" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"subjectId" UUID NOT NULL REFERENCES "StaffIdentity"("subjectId") ON DELETE RESTRICT ON UPDATE NO ACTION,"mfaEpoch" BIGINT NOT NULL CHECK("mfaEpoch">0),"enrollmentSessionId" TEXT NOT NULL,"secretEnvelope" TEXT NOT NULL CHECK(octet_length("secretEnvelope") BETWEEN 1 AND 256),"state" TEXT NOT NULL DEFAULT 'PENDING' CHECK("state" IN ('PENDING','ACTIVE','REVOKED')),"lastCounter" BIGINT NOT NULL DEFAULT -1 CHECK("lastCounter">=-1),"pendingExpiresAt" TIMESTAMPTZ(3) NOT NULL,"activatedAt" TIMESTAMPTZ(3),"revokedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(("state"='PENDING' AND "activatedAt" IS NULL AND "revokedAt" IS NULL) OR ("state"='ACTIVE' AND "activatedAt" IS NOT NULL AND "revokedAt" IS NULL) OR ("state"='REVOKED' AND "revokedAt" IS NOT NULL)));
CREATE INDEX "StaffMfaDevice_subjectId_mfaEpoch_state_idx" ON "StaffMfaDevice"("subjectId","mfaEpoch","state");
CREATE TABLE "StaffMfaProof" ("sessionId" TEXT PRIMARY KEY REFERENCES "Session"("id") ON DELETE CASCADE ON UPDATE NO ACTION,"subjectId" UUID NOT NULL REFERENCES "StaffIdentity"("subjectId") ON DELETE RESTRICT ON UPDATE NO ACTION,"deviceId" UUID NOT NULL REFERENCES "StaffMfaDevice"("id") ON DELETE RESTRICT ON UPDATE NO ACTION,"identityRevision" BIGINT NOT NULL CHECK("identityRevision">0),"mfaEpoch" BIGINT NOT NULL CHECK("mfaEpoch">0),"verifiedAt" TIMESTAMPTZ(3) NOT NULL,"expiresAt" TIMESTAMPTZ(3) NOT NULL CHECK("expiresAt">"verifiedAt"));
CREATE TABLE "StaffMfaRecoveryCode" ("hash" TEXT PRIMARY KEY CHECK("hash" ~ '^[a-f0-9]{64}$'),"subjectId" UUID NOT NULL REFERENCES "StaffIdentity"("subjectId") ON DELETE RESTRICT ON UPDATE NO ACTION,"mfaEpoch" BIGINT NOT NULL CHECK("mfaEpoch">0),"consumedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "StaffMfaRecoveryCode_subjectId_mfaEpoch_idx" ON "StaffMfaRecoveryCode"("subjectId","mfaEpoch");
CREATE TABLE "StaffMfaRecoveryPermit" ("sessionId" TEXT PRIMARY KEY REFERENCES "Session"("id") ON DELETE CASCADE ON UPDATE NO ACTION,"subjectId" UUID NOT NULL REFERENCES "StaffIdentity"("subjectId") ON DELETE RESTRICT ON UPDATE NO ACTION,"identityRevision" BIGINT NOT NULL CHECK("identityRevision">0),"mfaEpoch" BIGINT NOT NULL CHECK("mfaEpoch">0),"expiresAt" TIMESTAMPTZ(3) NOT NULL,"consumedAt" TIMESTAMPTZ(3));
CREATE TABLE "StaffMfaAttemptWindow" ("subjectId" UUID PRIMARY KEY REFERENCES "StaffIdentity"("subjectId") ON DELETE RESTRICT ON UPDATE NO ACTION,"startedAt" TIMESTAMPTZ(3) NOT NULL,"attempts" INTEGER NOT NULL CHECK("attempts" BETWEEN 0 AND 5));
CREATE TABLE "StaffMfaEvent" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"subjectId" UUID NOT NULL,"identityRevision" BIGINT NOT NULL CHECK("identityRevision">0),"mfaEpoch" BIGINT NOT NULL CHECK("mfaEpoch">0),"kind" TEXT NOT NULL CHECK("kind" IN ('ENROLLMENT_STARTED','DEVICE_CONFIRMED','MFA_VERIFIED','RECOVERY_CONSUMED','RECOVERY_CODES_ROTATED','DEVICE_REVOKED','KEY_REWRAPPED')),"deviceId" UUID,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "StaffMfaEvent_subjectId_createdAt_idx" ON "StaffMfaEvent"("subjectId","createdAt");
CREATE TRIGGER staff_mfa_event_immutable BEFORE UPDATE OR DELETE ON "StaffMfaEvent" FOR EACH ROW EXECUTE FUNCTION vera_staff_immutable();
CREATE TRIGGER staff_mfa_event_no_truncate BEFORE TRUNCATE ON "StaffMfaEvent" FOR EACH STATEMENT EXECUTE FUNCTION vera_staff_immutable();
CREATE TRIGGER staff_mfa_event_record_time BEFORE INSERT ON "StaffMfaEvent" FOR EACH ROW EXECUTE FUNCTION vera_staff_record_time();
CREATE FUNCTION vera_staff_device_transition() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF NEW."id" IS DISTINCT FROM OLD."id" OR NEW."subjectId" IS DISTINCT FROM OLD."subjectId" OR NEW."mfaEpoch" IS DISTINCT FROM OLD."mfaEpoch" OR NEW."enrollmentSessionId" IS DISTINCT FROM OLD."enrollmentSessionId" OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" OR NEW."pendingExpiresAt" IS DISTINCT FROM OLD."pendingExpiresAt" OR NEW."lastCounter"<OLD."lastCounter" OR (OLD."activatedAt" IS NOT NULL AND NEW."activatedAt" IS DISTINCT FROM OLD."activatedAt") OR (OLD."state"='REVOKED' AND NEW."state"<>'REVOKED') OR (OLD."state"='ACTIVE' AND NEW."state"='PENDING') THEN RAISE EXCEPTION 'STAFF_DEVICE_TRANSITION_INVALID' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_mfa_device_transition BEFORE UPDATE ON "StaffMfaDevice" FOR EACH ROW EXECUTE FUNCTION vera_staff_device_transition();
CREATE TRIGGER staff_mfa_device_no_delete BEFORE DELETE ON "StaffMfaDevice" FOR EACH ROW EXECUTE FUNCTION vera_staff_immutable();
CREATE TRIGGER staff_mfa_device_no_truncate BEFORE TRUNCATE ON "StaffMfaDevice" FOR EACH STATEMENT EXECUTE FUNCTION vera_staff_immutable();
CREATE FUNCTION vera_staff_recovery_consumption() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF NEW."hash" IS DISTINCT FROM OLD."hash" OR NEW."subjectId" IS DISTINCT FROM OLD."subjectId" OR NEW."mfaEpoch" IS DISTINCT FROM OLD."mfaEpoch" OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" OR (OLD."consumedAt" IS NOT NULL AND NEW."consumedAt" IS DISTINCT FROM OLD."consumedAt") THEN RAISE EXCEPTION 'STAFF_RECOVERY_IMMUTABLE' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_mfa_recovery_consumption BEFORE UPDATE ON "StaffMfaRecoveryCode" FOR EACH ROW EXECUTE FUNCTION vera_staff_recovery_consumption();
CREATE TRIGGER staff_mfa_recovery_no_delete BEFORE DELETE ON "StaffMfaRecoveryCode" FOR EACH ROW EXECUTE FUNCTION vera_staff_immutable();
CREATE TRIGGER staff_mfa_recovery_no_truncate BEFORE TRUNCATE ON "StaffMfaRecoveryCode" FOR EACH STATEMENT EXECUTE FUNCTION vera_staff_immutable();
